import{_ as t,c as a,o as r,a0 as n}from"./chunks/framework.DKRgXLPU.js";const i=JSON.parse('{"title":"Mentala spelövningar - arbetsblad","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/sv/exercise-worksheets.md","filePath":"public/downloads/sv/exercise-worksheets.md"}');const e=t({name:"public/downloads/sv/exercise-worksheets.md"},[["render",function(t,i,e,_,l,s){return r(),a("div",null,[...i[0]||(i[0]=[n('<h1 id="mentala-spelovningar-arbetsblad" tabindex="-1">Mentala spelövningar - arbetsblad <a class="header-anchor" href="#mentala-spelovningar-arbetsblad" aria-label="Permalink to &quot;Mentala spelövningar - arbetsblad&quot;">​</a></h1><p><strong>Pétanque Academy - Praktiska övningar</strong></p><hr><h2 id="ovning-1-reflektion-av-flodestillstand" tabindex="-1">Övning 1: Reflektion av flödestillstånd <a class="header-anchor" href="#ovning-1-reflektion-av-flodestillstand" aria-label="Permalink to &quot;Övning 1: Reflektion av flödestillstånd&quot;">​</a></h2><h3 id="nar-har-du-upplevt-flode" tabindex="-1">När har du upplevt flöde? <a class="header-anchor" href="#nar-har-du-upplevt-flode" aria-label="Permalink to &quot;När har du upplevt flöde?&quot;">​</a></h3><p>Tänk på en gång när du spelade din bästa boule:</p><p><strong>Beskriv situationen:</strong></p><ul><li>Vilken turnering/match var det?</li><li>Vilka var villkoren?</li><li>Vilka spelade du med?</li></ul><hr><hr><p><strong>Hur kändes det?</strong></p><ul><li>Hur var ditt mentala tillstånd?</li><li>Hur kändes tiden?</li><li>Vad tänkte du (eller tänkte inte)?</li></ul><hr><hr><p><strong>Vad hjälpte dig att komma dit?</strong></p><ul><li>Vad gjorde du före matchen?</li><li>Vad var annorlunda med den dagen?</li><li>Kan du återskapa någon av dessa förhållanden?</li></ul><hr><hr><hr><h2 id="ovning-2-inventering-av-inre-kritiker" tabindex="-1">Övning 2: Inventering av inre kritiker <a class="header-anchor" href="#ovning-2-inventering-av-inre-kritiker" aria-label="Permalink to &quot;Övning 2: Inventering av inre kritiker&quot;">​</a></h2><h3 id="identifiera-din-inre-kritiker" tabindex="-1">Identifiera din inre kritiker <a class="header-anchor" href="#identifiera-din-inre-kritiker" aria-label="Permalink to &quot;Identifiera din inre kritiker&quot;">​</a></h3><p><strong>Vad säger din inre kritiker?</strong></p><p>Lista 3–5 vanliga kritiska tankar du har under tävlingar:</p><ol><li><hr></li><li><hr></li><li><hr></li><li><hr></li><li><hr></li></ol><p><strong>När dyker den upp?</strong></p><ul><li>Efter misstag? □</li><li>Innan viktiga bilder? □</li><li>När man spelar mot starka motståndare? □</li><li>När lagkamraterna tittar på? □</li><li>Annat: _______________________________________________</li></ul><hr><h2 id="ovning-3-omformuleringsovning" tabindex="-1">Övning 3: Omformuleringsövning <a class="header-anchor" href="#ovning-3-omformuleringsovning" aria-label="Permalink to &quot;Övning 3: Omformuleringsövning&quot;">​</a></h2><h3 id="forvandla-kritiker-till-coach" tabindex="-1">Förvandla kritiker till coach <a class="header-anchor" href="#forvandla-kritiker-till-coach" aria-label="Permalink to &quot;Förvandla kritiker till coach&quot;">​</a></h3><p><strong>För varje tanke från den inre kritikern, skriv en omformulering av den inre coachen:</strong></p><table tabindex="0"><thead><tr><th>Inre kritiker</th><th>Inre coach</th></tr></thead><tbody><tr><td>Exempel: &quot;Jag misslyckas alltid under press&quot;</td><td>&quot;Jag har lyckats under press förut, jag kan göra det igen&quot;</td></tr><tr><td>1. ________________________</td><td>_________________________</td></tr><tr><td>2. _________________________</td><td>_________________________</td></tr><tr><td>3. ________________________</td><td>_________________________</td></tr></tbody></table><p><strong>Öva på att säga dessa högt</strong></p><hr><h2 id="ovning-4-utformning-av-rutiner-fore-skott" tabindex="-1">Övning 4: Utformning av rutiner före skott <a class="header-anchor" href="#ovning-4-utformning-av-rutiner-fore-skott" aria-label="Permalink to &quot;Övning 4: Utformning av rutiner före skott&quot;">​</a></h2><h3 id="skapa-din-personliga-rutin" tabindex="-1">Skapa din personliga rutin <a class="header-anchor" href="#skapa-din-personliga-rutin" aria-label="Permalink to &quot;Skapa din personliga rutin&quot;">​</a></h3><p>Utforma en rutin i fyra steg före behandlingen som fungerar för dig:</p><p><strong>Steg 1: Visualisera</strong></p><ul><li>Vad exakt kommer du att visualisera?</li><li>Hur länge (2-3 sekunder)?</li></ul><hr><p><strong>Steg 2: Andas</strong></p><ul><li>Ett djupt andetag eller tre?</li><li>Något specifikt mönster?</li></ul><hr><p><strong>Steg 3: Ankare</strong></p><ul><li>Vilket fysiskt ankare kommer du att använda?</li><li>Touch-boule? Specifik ställning?</li></ul><hr><p><strong>Steg 4: Utför</strong></p><ul><li>Vad är din mentala ledtråd?</li><li>&quot;Förtroende&quot; / &quot;Flöde&quot; / &quot;Gå&quot;?</li></ul><hr><p><strong>Öva denna rutin 10 gånger idag</strong></p><hr><h2 id="ovning-5-tryckutlosare" tabindex="-1">Övning 5: Tryckutlösare <a class="header-anchor" href="#ovning-5-tryckutlosare" aria-label="Permalink to &quot;Övning 5: Tryckutlösare&quot;">​</a></h2><h3 id="identifiera-dina-tryckpunkter" tabindex="-1">Identifiera dina tryckpunkter <a class="header-anchor" href="#identifiera-dina-tryckpunkter" aria-label="Permalink to &quot;Identifiera dina tryckpunkter&quot;">​</a></h3><p><strong>Vilka situationer skapar press för dig?</strong></p><p>Betygsätt varje från 1 (inget tryck) till 10 (extremt tryck):</p><ul><li>Spelar mot starka motståndare: ___/10</li><li>Viktiga turneringsmatcher: ___/10</li><li>Oavgjort resultat, sista skottet: ___/10</li><li>Efter att ha gjort ett misstag: ___/10</li><li>När lagkamrater tittar: ___/10</li><li>När jag spelar dåligt: ___/10</li><li>Annat: ___________________________ ___/10</li></ul><p><strong>För din högst rankade trigger:</strong></p><p>Vilka fysiska förnimmelser märker du?</p><hr><p>Vilka tankar dyker upp?</p><hr><p>Vilken teknik kommer du att använda?</p><ul><li>[ ] 3-Andetagsåterställning</li><li>[ ] Rutin före skotttagning</li><li>[ ] Omformning</li><li>[ ] Annat: _____________________</li></ul><hr><h2 id="ovning-6-lagesvaxlingsovning" tabindex="-1">Övning 6: Lägesväxlingsövning <a class="header-anchor" href="#ovning-6-lagesvaxlingsovning" aria-label="Permalink to &quot;Övning 6: Lägesväxlingsövning&quot;">​</a></h2><h3 id="planering-kontra-utforande" tabindex="-1">Planering kontra utförande <a class="header-anchor" href="#planering-kontra-utforande" aria-label="Permalink to &quot;Planering kontra utförande&quot;">​</a></h3><p><strong>Öva på växlingen:</strong></p><p><strong>Planeringsfas (före inspelning):</strong></p><ul><li>Vad behöver jag analysera?</li><li>Vad är min strategi?</li><li>Vilket skott ska jag välja?</li></ul><p><strong>Utförandefas (under inspelning):</strong></p><ul><li>Rensa ditt sinne</li><li>Lita på din kropp</li><li>Låt det hända</li></ul><p><strong>Övning:</strong></p><p>Ta 5 övningsskott. För varje:</p><ol><li>Tillbringa 10 sekunder i planeringsläge (analysera, besluta)</li><li>Ta 3 andetag för att byta läge</li><li>Kör i flödesläge (inget tänkande)</li></ol><p><strong>Reflexion:</strong></p><ul><li>Kunde du känna skillnaden mellan lägena?</li><li>Var växlingen tydlig?</li><li>Vilket läge är svårare för dig?</li></ul><hr><hr><hr><h2 id="ovning-7-veckovis-traningsplan" tabindex="-1">Övning 7: Veckovis träningsplan <a class="header-anchor" href="#ovning-7-veckovis-traningsplan" aria-label="Permalink to &quot;Övning 7: Veckovis träningsplan&quot;">​</a></h2><h3 id="denna-veckas-fokus" tabindex="-1">Denna veckas fokus <a class="header-anchor" href="#denna-veckas-fokus" aria-label="Permalink to &quot;Denna veckas fokus&quot;">​</a></h3><p><strong>Välj EN teknik att öva på:</strong></p><ul><li>[ ] 3-Andningsåterställning efter varje misstag</li><li>[ ] Förskottsrutin vid varje kast</li><li>[ ] Omformulera en Inre Kritiker-tanke per session</li><li>[ ] Växling av övningsläge</li></ul><p><strong>Daglig träning:</strong></p><table tabindex="0"><thead><tr><th>Dag</th><th>Övningsaktivitet</th><th>Varaktighet</th><th>Anteckningar</th></tr></thead><tbody><tr><td>mån</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>tis</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Ons</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>tors</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Fre</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>lör</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Sol</td><td>________________</td><td>___min</td><td>________________</td></tr></tbody></table><hr><h2 id="ovning-8-framstegssparning" tabindex="-1">Övning 8: Framstegsspårning <a class="header-anchor" href="#ovning-8-framstegssparning" aria-label="Permalink to &quot;Övning 8: Framstegsspårning&quot;">​</a></h2><h3 id="reflektion-vid-veckans-slut" tabindex="-1">Reflektion vid veckans slut <a class="header-anchor" href="#reflektion-vid-veckans-slut" aria-label="Permalink to &quot;Reflektion vid veckans slut&quot;">​</a></h3><p><strong>Vad har du övat på den här veckan?</strong></p><hr><p><strong>Vad lade du märke till?</strong></p><hr><hr><p><strong>Vad fungerade bra?</strong></p><hr><hr><p><strong>Vad var utmanande?</strong></p><hr><hr><p><strong>Vad fortsätter du med nästa vecka?</strong></p><hr><hr><p><strong>Vad kommer du att justera?</strong></p><hr><hr><hr><h2 id="nasta-steg" tabindex="-1">Nästa steg <a class="header-anchor" href="#nasta-steg" aria-label="Permalink to &quot;Nästa steg&quot;">​</a></h2><h3 id="fortsatt-din-utveckling" tabindex="-1">Fortsätt din utveckling <a class="header-anchor" href="#fortsatt-din-utveckling" aria-label="Permalink to &quot;Fortsätt din utveckling&quot;">​</a></h3><p><strong>Resurser på carreau.app:</strong></p><ul><li>Målmall - Strukturera din långsiktiga utveckling</li><li>Dagboksmall - Följ dagliga framsteg</li><li>Zonen - Djupdykning i flödestillstånd</li><li>Mental styrka - Avancerad presshantering</li></ul><p><strong>Fortsätt öva:</strong></p><ul><li>Mentala färdigheter behöver regelbunden träning</li><li>Börja smått, bygg upp gradvis</li><li>Följ dina framsteg</li><li>Fira förbättringar</li></ul><hr><p><em>Pétanque Academy - Elite Player Development</em><em>carreau.app</em></p>',113)])])}]]);export{i as __pageData,e as default};
